contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address baseToken, address nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public payable {
        require(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ); if (__ESBMC_reverted()) return;

        address observedBaseToken = c.baseToken(); if (__ESBMC_reverted()) return;

        assert(observedBaseToken == baseToken);
    }

    receive() external payable {}
}

