pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(address baseToken, address nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) internal {
        feeRate = uint16(bound(uint256(feeRate), 0, 5000));
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {} catch { return; }
        address observedBaseToken;
        try c.baseToken() returns (address __r) { observedBaseToken = __r; } catch { return; }
        assertTrue(observedBaseToken == baseToken);
    }

    function testFuzz_run(address baseToken, address nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public {
        vm.assume(baseToken.code.length == 0 && uint160(baseToken) > 0xffff && baseToken != address(this) && baseToken != address(c) && baseToken != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && baseToken != 0x000000000000000000636F6e736F6c652e6c6f67 && baseToken != 0x4e59b44847b379578588920cA78FbF26c0B4956C && baseToken != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(nft.code.length == 0 && uint160(nft) > 0xffff && nft != address(this) && nft != address(c) && nft != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && nft != 0x000000000000000000636F6e736F6c652e6c6f67 && nft != 0x4e59b44847b379578588920cA78FbF26c0B4956C && nft != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties);
    }

    receive() external payable {}
}
